    '{ 32'h85D17040, 32'h85D19040, 32'h00001000, 32'h20174000, 32'h10000000 },
    '{ 32'h8BA2F080, 32'h8BA2E080, 32'h00002000, 32'h202E8000, 32'h10000000 },
    '{ 32'h917470C0, 32'h917450C0, 32'h00003000, 32'h2045C000, 32'h10000000 },
    '{ 32'h9745C100, 32'h9745D100, 32'h00004000, 32'h205D0000, 32'h10000000 },
    '{ 32'h9D173140, 32'h9D175140, 32'h00005000, 32'h20744000, 32'h10000000 },
    '{ 32'hA2E8B180, 32'hA2E8A180, 32'h00006000, 32'h208B8000, 32'h10000000 },
    '{ 32'hA8BA31C0, 32'hA8BA11C0, 32'h00007000, 32'h20A2C000, 32'h10000000 },
    '{ 32'hAE8B8200, 32'hAE8B9200, 32'h00008000, 32'h20BA0000, 32'h10000000 },
    '{ 32'hB45CF240, 32'hB45D1240, 32'h00009000, 32'h20D14000, 32'h10000000 },
    '{ 32'hBA2E7280, 32'hBA2E6280, 32'h0000A000, 32'h20E88000, 32'h10000000 }
  };
  localparam bit HAS_UNMAPPED = 1;
  localparam logic [31:0] UNMAPPED_ADDR = 32'h00010000;
endpackage
`endif
